`timescale 1ns/1ps
// Vectors are generated by verify_softmax_exp.py using the Python model.
module tb_softmax_exp;
    localparam int MAX_LENGTH=32;
    localparam int COUNT_WIDTH=$clog2(MAX_LENGTH+1);
    logic clk=0, rst_n=0, start=0, in_valid=0;
    logic [COUNT_WIDTH-1:0] row_length=0;
    logic signed [31:0] in_data=0;
    wire in_ready, done, exp_valid;
    wire signed [31:0] max_value;
    wire [15:0] exp_data;
    logic signed [31:0] samples[0:MAX_LENGTH-1];
    logic signed [32:0] expected_diff[0:MAX_LENGTH-1];
    logic [15:0] expected_bf16[0:MAX_LENGTH-1], expected_exp[0:MAX_LENGTH-1];
    logic signed [31:0] expected_max;
    integer fd, status, n, rows=0, elements=0;
    string vector_path;
    softmax_exp dut(.*);
    always #2.5 clk=~clk; // 5 ns period (200 MHz)

    task automatic reset_dut;
        @(negedge clk); rst_n=0; start=0; in_valid=0;
        #1;
        if (exp_valid !== 0 || done !== 0 || in_ready !== 0)
            $fatal(1,"Reset did not clear control outputs");
        @(negedge clk); rst_n=1;
    endtask

    task automatic begin_row(input integer length);
        @(negedge clk); start=1; row_length=length;
        @(posedge clk); #1;
        if(in_ready !== 1 || exp_valid !== 0 || done !== 0)
            $fatal(1,"Start failed");
        @(negedge clk); start=0; row_length=0;
    endtask

    initial begin
        if (!$value$plusargs("VECTORS=%s",vector_path))
            $fatal(1,"Run through verify_softmax_exp.py or supply +VECTORS=path");
        fd=$fopen(vector_path,"r");
        if(!fd) $fatal(1,"Cannot open vectors");
        reset_dut();
        // Reject invalid lengths and valid without start.
        @(negedge clk); in_valid=1;
        @(posedge clk); #1;
        if(in_ready || exp_valid || done) $fatal(1,"Unexpected start");
        @(negedge clk); in_valid=0; start=1; row_length=0;
        @(posedge clk); #1;
        if(in_ready || exp_valid || done) $fatal(1,"Accepted empty row");
        @(negedge clk); row_length=MAX_LENGTH+1;
        @(posedge clk); #1;
        if(in_ready || exp_valid || done) $fatal(1,"Accepted oversized row");
        @(negedge clk); start=0;

        // Abort a row while receiving, then another while output is valid.
        begin_row(2); in_valid=1; in_data=7;
        @(posedge clk); #1; reset_dut();
        begin_row(2);
        for(integer i=0;i<2;i=i+1) begin
            in_valid=1; in_data=i;
            @(posedge clk); #1; @(negedge clk);
        end
        in_valid=0;
        @(posedge clk); #1;
        if(exp_valid || done) $fatal(1,"Early valid during RAM read");
        repeat(3) begin @(posedge clk); #1; end
        if(exp_valid !== 1) $fatal(1,"Expected output before abort");
        reset_dut();

        while (!$feof(fd)) begin
            status=$fscanf(fd,"%d %h",n,expected_max);
            if(status==2) begin
                if(n<1 || n>MAX_LENGTH) $fatal(1,"Bad vector length");
                for(integer i=0;i<n;i=i+1) begin
                    status=$fscanf(fd,"%h %h %h %h",samples[i],expected_diff[i],
                                   expected_bf16[i],expected_exp[i]);
                    if(status!=4) $fatal(1,"Malformed vector");
                end
                begin_row(n);
                for(integer i=0;i<n;i=i+1) begin
                    if(i%3==1) begin
                        in_valid=0; in_data=32'sh7fffffff;
                        @(posedge clk); #1;
                        if(exp_valid !== 0 || done !== 0) $fatal(1,"Output during input bubble");
                        @(negedge clk);
                    end
                    in_valid=1; in_data=samples[i];
                    if(in_ready !== 1) $fatal(1,"Input not ready");
                    @(posedge clk); #1;
                    if(exp_valid !== 0 || done !== 0) $fatal(1,"Premature output");
                    @(negedge clk);
                end
                @(posedge clk); #1; if(exp_valid || done) $fatal(1,"Early output during RAM read");
                // These inputs must be ignored while emitting results.
                in_valid=1; in_data=32'sh7fffffff;
                // At cycle i the converter sees input i, the output carries i-2.
                for(integer i=0;i<n+2;i=i+1) begin
                    @(posedge clk); #1;
                    if(dut.diff_valid !== (i<n) || exp_valid !== (i>=2) ||
                       done !== (i==n+1) || in_ready !== 0)
                        $fatal(1,"Row %0d cycle %0d: valid/done timing",rows,i);
                    if(i<n && (dut.diff_data !== expected_diff[i] ||
                               dut.diff_bf16 !== expected_bf16[i]))
                        $fatal(1,"Row %0d index %0d: conversion mismatch",rows,i);
                    if(i>=2) begin
                        if(max_value !== expected_max || exp_data !== expected_exp[i-2])
                            $fatal(1,"Row %0d index %0d: exp=%h expected=%h",
                                   rows,i-2,exp_data,expected_exp[i-2]);
                        elements=elements+1;
                    end
                    @(negedge clk);
                end
                in_valid=0;
                @(posedge clk); #1;
                if(exp_valid !== 0 || done !== 0 || in_ready !== 0)
                    $fatal(1,"Extra output after row");
                rows=rows+1;
            end else if(!$feof(fd)) $fatal(1,"Malformed row header");
        end
        $fclose(fd);
        if(rows==0) $fatal(1,"No test rows");
        $display("PASS: %0d rows, %0d results match Python at subtract, BF16 and VEXP; timing/reset passed",rows,elements);
        $finish;
    end
    initial begin #2000000; $fatal(1,"Timeout"); end
endmodule
